OmniUiCard.stylingConfiguration:
{"customStyles":".accordianCustomSection button[class="slds-button slds-p-horizontal_x-small"] {
 background: #f3f3f3;
 width: 100%;
}

.labelClass{
 margin-top: 4rem;
}

.underlineCustom{
 border-bottom: 1px solid rgb(229,229,229);
}

.customRequired:before{
 content: '*';
 color: var(--slds-g-color-error-base-40, var(--lwc-colorTextError,rgb(234, 0, 30)));
 margin: 0 var(--lwc-spacingXxxSmall,0.125rem);
}

.hideLabelCustom label .slds-form-element__label.slds-show--inline.slds-p-top_none {
 display: none; 
}


"}
